draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // brain
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 100, 0, 2 * Math.PI);
  ctx.stroke();

  // thoughts
  ctx.lineWidth = 2;
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.arc(W/2 + Math.cos(t + i) * 50, H/2 + Math.sin(t + i) * 50, 10, 0, 2 * Math.PI);
    ctx.stroke();
  }

  // stick figure
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 120, 20, 0, 2 * Math.PI); // head
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 140);
  ctx.lineTo(W/2, H/2 + 200); // body
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 160);
  ctx.lineTo(W/2 - 30, H/2 + 180); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 160);
  ctx.lineTo(W/2 + 30, H/2 + 180); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 200);
  ctx.lineTo(W/2 - 20, H/2 + 220); // leg
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 200);
  ctx.lineTo(W/2 + 20, H/2 + 220); // leg
  ctx.stroke();

  ctx.restore();
}
